local.file "observability_m2m_client_id" {
  filename = "/var/run/secrets/observability-m2m/client_id"
}
local.file "alertmanager_global" {
  filename = "/etc/alloy/alertmanager-global/config"
}
mimir.rules.kubernetes "mimir" {
  address       = "https://mimir.cloud.witl.xyz"
  sync_interval = "2m"
  oauth2 {
    token_url           = "https://auth.cloud.witl.xyz/application/o/token/"
    client_id           = string.trim_space(local.file.observability_m2m_client_id.content)
    client_secret_file  = "/var/run/secrets/observability-m2m/client_secret"
    scopes              = ["openid", "tenant", "mimir:write", "mimir:read"]
    endpoint_params     = { "grant_type" = "client_credentials" }
  }
}
mimir.alerts.kubernetes "mimir" {
  address       = "https://mimir.cloud.witl.xyz"
  global_config = local.file.alertmanager_global.content
  sync_interval = "2m"
  oauth2 {
    token_url           = "https://auth.cloud.witl.xyz/application/o/token/"
    client_id           = string.trim_space(local.file.observability_m2m_client_id.content)
    client_secret_file  = "/var/run/secrets/observability-m2m/client_secret"
    scopes              = ["openid", "tenant", "mimir:write", "mimir:read"]
    endpoint_params     = { "grant_type" = "client_credentials" }
  }
}
